import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const m=JSON.parse('{"title":"大卫·索科尔 (David Sokol)","description":"","frontmatter":{},"headers":[],"relativePath":"04_people/大卫·索科尔.md","filePath":"04_people/大卫·索科尔.md"}'),i={name:"04_people/大卫·索科尔.md"};function l(n,a,h,d,s,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="大卫·索科尔-david-sokol" tabindex="-1">大卫·索科尔 (David Sokol) <a class="header-anchor" href="#大卫·索科尔-david-sokol" aria-label="Permalink to &quot;大卫·索科尔 (David Sokol)&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>全名</strong></td><td>David L. Sokol</td></tr><tr><td><strong>公司</strong></td><td>MidAmerican Energy Holdings Company</td></tr><tr><td><strong>职位</strong></td><td>前首席执行官 (CEO)</td></tr></tbody></table><h2 id="职业生涯" tabindex="-1">职业生涯 <a class="header-anchor" href="#职业生涯" aria-label="Permalink to &quot;职业生涯&quot;">​</a></h2><h3 id="早年" tabindex="-1">早年 <a class="header-anchor" href="#早年" aria-label="Permalink to &quot;早年&quot;">​</a></h3><p>大卫·索科尔出生于美国威斯康星州沃沙市（Wausau, Wisconsin）。他的商业才能在早年便已显露，在进入能源行业之前，索科尔曾在多个领域积累丰富的企业运营与管理经验。</p><h3 id="midamerican-energy" tabindex="-1">MidAmerican Energy <a class="header-anchor" href="#midamerican-energy" aria-label="Permalink to &quot;MidAmerican Energy&quot;">​</a></h3><p>1990年代，索科尔通过一系列战略性并购，创建了 MidAmerican Energy Holdings Company。这家能源公司迅速成长为美国中西部地区重要的公用事业企业，业务覆盖电力生产、传输与配送。</p><h2 id="与伯克希尔的关系" tabindex="-1">与伯克希尔的关系 <a class="header-anchor" href="#与伯克希尔的关系" aria-label="Permalink to &quot;与伯克希尔的关系&quot;">​</a></h2><p>2000年，<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a> 执掌的 <a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> 收购了 MidAmerican Energy。在被收购后，索科尔被继续留任为 MidAmerican CEO，这一安排充分体现了巴菲特对其管理能力的高度信任。</p><p>作为被收购公司的管理者，索科尔展现出卓越的业绩。MidAmerican 在他领导下持续壮大，逐步成为伯克希尔能源业务板块的核心资产，也就是后来的 <a href="/03_companies/中美能源.html">中美能源</a>（MidAmerican Energy Holdings Company）。</p><h2 id="为何曾是接班热门" tabindex="-1">为何曾是接班热门 <a class="header-anchor" href="#为何曾是接班热门" aria-label="Permalink to &quot;为何曾是接班热门&quot;">​</a></h2><p>在2008年前后，鉴于以下原因，索科尔被外界普遍视为 <a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a> 最可能的接班人候选：</p><ul><li><strong>丰富的企业管理经验</strong>：作为大型能源公司的掌舵者，索科尔具备运营大型综合性企业的实战能力</li><li><strong>与巴菲特的信任关系</strong>：成功管理被伯克希尔收购的公司超过8年，深得巴菲特认可</li><li><strong>能源业务契合度</strong>：伯克希尔拥有大量能源类资产，索科尔的专业背景与伯克希尔的业务结构高度匹配</li></ul><h2 id="_2011年辞职事件" tabindex="-1">2011年辞职事件 <a class="header-anchor" href="#_2011年辞职事件" aria-label="Permalink to &quot;2011年辞职事件&quot;">​</a></h2><h3 id="事件经过" tabindex="-1">事件经过 <a class="header-anchor" href="#事件经过" aria-label="Permalink to &quot;事件经过&quot;">​</a></h3><p>2011年初，索科尔被曝出在<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> 即将宣布收购调味品公司 Perfection Foods 之前，购买了该公司的股票。这一行为引发了市场对其是否涉及内幕交易的质疑。</p><p>在舆论压力下，索科尔选择主动辞职，离开了他服务多年的伯克希尔系公司。</p><h3 id="巴菲特的澄清" tabindex="-1">巴菲特的澄清 <a class="header-anchor" href="#巴菲特的澄清" aria-label="Permalink to &quot;巴菲特的澄清&quot;">​</a></h3><p>随后，<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a> 在2011年致股东信中明确表态：</p><blockquote><p>&quot;索科尔没有做错任何事，没有违法行为。&quot;</p></blockquote><p>巴菲特进一步解释称，索科尔购买股票时，并不知道伯克希尔即将收购 Perfection Foods，完全是个人独立决策。<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a> 甚至表示，是他本人说服索科尔购买该股票的，这一责任应由自己承担。</p><p>这一澄清彻底还了索科尔清白，尽管如此，索科尔仍决定辞去相关职务，退出公众视野。</p><h2 id="后续与接班人格局" tabindex="-1">后续与接班人格局 <a class="header-anchor" href="#后续与接班人格局" aria-label="Permalink to &quot;后续与接班人格局&quot;">​</a></h2><p>索科尔离职后，<a href="/04_people/格雷格·阿贝尔.html">格雷格·阿贝尔</a>（Greg Abel）逐渐成为巴菲特接班人的首选。2021年，阿贝尔正式被任命为伯克希尔副董事长，负责除保险业务外的所有日常运营工作。</p><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a></li><li><a href="/03_companies/中美能源.html">中美能源</a></li><li><a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a></li><li><a href="/04_people/格雷格·阿贝尔.html">格雷格·阿贝尔</a></li></ul>',27)])])}const _=e(i,[["render",l]]);export{m as __pageData,_ as default};
